bool AWeaponLoop::AttachItem(FName Slot,FName Item){if(!ProfileReady)return false;if(ActiveProfile){if(Mode!=TEXT("idle")||Cooldown>0)return false;const FString* Allowed=ActiveProfile->AllowedSlots.Find(Slot);if(!Allowed||*Allowed!=Item.ToString()){Message=TEXT("Incompatible attachment");return false;}Grip=Item;Message=TEXT("Finish: ")+Item.ToString();return true;}if(Slot!=TEXT("grip")||(Item!=TEXT("walnut")&&Item!=TEXT("charcoal"))){Message=TEXT("Incompatible attachment");return false;}if(Mode!=TEXT("idle"))return false;Grip=Item;for(auto M:Grips)M->SetVectorParameterValue(TEXT("BaseColorFactor"),Grip==TEXT("walnut")?FLinearColor::White:FLinearColor(FColor(102,121,134)));Message=TEXT("Grip: ")+Grip.ToString();return true;}
bool AWeaponLoop::Action(FName Name){if(!ProfileReady){Message=TEXT("Weapon profile unavailable");return false;}
 // Held-trigger guns: a fire action is a pull and a release (the round falls in the next frame); the trigger owns the cadence.
 if(UsesTrigger()){bool Ok;if(Name==TEXT("fire")){Ok=TriggerGun.Trigger.Pull();TriggerGun.Trigger.Release();}else if(Name==TEXT("mode")){Ok=TriggerGun.Trigger.CycleMode(TriggerGun.Rules->Fire);if(Ok)TriggerGun.Message=FString(TEXT("Mode: "))+WeaponTrigger::ModeName(TriggerGun.Trigger.Mode);}else Ok=TriggerGun.Command(Name);SyncTriggerGun();return Ok;}
 if(ActiveProfile&&(Mode!=TEXT("idle")||Cooldown>0))return false;if(Name==TEXT("aim")){if(Mode!=TEXT("idle"))return false;Aim=!Aim;Message=Aim?TEXT("Aim"):TEXT("Ready");return true;}if(Name==TEXT("inspect")){if(Mode!=TEXT("idle"))return false;Mode=Name;Timer=ActiveProfile?ActiveProfile->InspectDuration:WeaponPresentation::InspectDuration;Aim=false;Message=TEXT("Inspect");return true;}if(Name==TEXT("reload")){if(Mode!=TEXT("idle")||Ammo==Capacity()||Reserve==0)return false;Mode=Name;Timer=ActiveProfile?ActiveProfile->ReloadDuration:WeaponPresentation::ReloadDuration;ReloadCommitted=false;Aim=false;Message=TEXT("Reload");return true;}if(Name==TEXT("fire")){if(Mode!=TEXT("idle")||Cooldown>0)return false;const FString CommandId=FString::Printf(TEXT("native-command-%d"),Shots+1);
  // Owner decision (27 Oct): with no string running, the trigger starts one in the current lane; a docked paper deploys first and the string begins on arrival.
  if(Ammo&&(Range.Phase==TEXT("ready")||Range.Phase==TEXT("review")))Range.Action(TEXT("start"));if(!Range.CanRecord(CommandId)){Message=Ammo?Range.Message:FString(TEXT("Empty - reload"));return false;}if(!Ammo){Message=TEXT("Empty - reload");return false;}auto* P=Cast<ARangeSlicePawn>(UGameplayStatics::GetPlayerPawn(this,0));if(!P||!Range.RecordShot(CommandId,P->Camera->GetComponentLocation(),P->Camera->GetForwardVector()))return false;Recoil.Fire(Range.Id,Range.LastShot()->Id);Ammo--;Shots++;Hits+=Range.LastShot()&&Range.LastShot()->Outcome==TEXT("hit")?1:0;Cooldown=ActiveProfile?ActiveProfile->FireDuration:.22f;if(ActiveProfile){Mode=TEXT("cycling");Timer=Cooldown;}Flash=.09f;Message=Range.Message;return true;}return false;}
void AWeaponLoop::Check(bool C,const TCHAR*N){Failed|=!C;UE_LOG(LogTemp,Display,TEXT("WEAPON_CHECK %s %s"),N,C?TEXT("PASS"):TEXT("FAIL"));}
// Recoil v1: step the kick and turn the pawn's look by the change: camera pitch inside the mouse-look clamp, actor yaw.
void AWeaponLoop::TickRecoil(float Dt){
 const FName Id=ActiveProfile?ActiveProfile->ProfileId:FName(TEXT("pistol"));if(!Recoil.Profile||Id!=FName(Recoil.Profile->Id))Recoil.Reset(WeaponRecoilData::Find(Id));
 RecoilOwed+=Recoil.Step(Dt);ApplyRecoilTurn();
}
void AWeaponLoop::ApplyRecoilTurn(){
 auto* P=Cast<ARangeSlicePawn>(UGameplayStatics::GetPlayerPawn(this,0));if(!P)return;
 // Scene components ignore rotation changes under 1e-4 deg, which would drop the tail of every recovery, so the turn is carried until it is
 // at least 2e-4 deg and the owed amount is reduced by what was actually applied. A clamped pitch discards the rest, as mouse look does.
 if(FMath::Abs(RecoilOwed.X)>=2e-4){FRotator Look=P->Camera->GetRelativeRotation();const double From=Look.Pitch,To=From+RecoilOwed.X;Look.Pitch=FMath::Clamp(To,-75.,75.);P->Camera->SetRelativeRotation(Look);RecoilOwed.X=Look.Pitch!=To?0:RecoilOwed.X-(P->Camera->GetRelativeRotation().Pitch-From);}
 if(FMath::Abs(RecoilOwed.Y)>=2e-4){const double From=P->GetActorRotation().Yaw;P->AddActorWorldRotation(FRotator(0,RecoilOwed.Y,0));RecoilOwed.Y-=FRotator::NormalizeAxis(P->GetActorRotation().Yaw-From);}
 if(RecoilProbe.Active)RecoilProbe.Peak=FMath::Max(RecoilProbe.Peak,P->Camera->GetComponentRotation().Pitch-RecoilProbe.Before.Pitch);
}
void AWeaponLoop::BeginRecoilProbe(){RecoilProbe=FRecoilProbe();if(auto* P=Cast<ARangeSlicePawn>(UGameplayStatics::GetPlayerPawn(this,0))){RecoilProbe.Active=true;RecoilProbe.Before=P->Camera->GetComponentRotation();RecoilProbe.Forward=P->Camera->GetForwardVector();RecoilProbe.Shots=Recoil.Shots;}}
// The accepted shot left along the aim from before its kick, and kicked exactly once.
bool AWeaponLoop::RecoilProbeShot(){RecoilProbe.Kick=Recoil.LastKick;return RecoilProbe.Active&&Recoil.Shots==RecoilProbe.Shots+1&&Range.LastShot()&&Range.LastShot()->RayDirection.Equals(RecoilProbe.Forward,1e-6);}
// Once settled, the look has turned by the residual share of the kick, after rising past half the kick.
bool AWeaponLoop::RecoilProbeSettled(){
 auto* P=Cast<ARangeSlicePawn>(UGameplayStatics::GetPlayerPawn(this,0));if(!P||!RecoilProbe.Active||!Recoil.Profile)return false;RecoilProbe.Active=false;
 const FRotator Now=P->Camera->GetComponentRotation();const double Keep=Recoil.Profile->Residual,DP=Now.Pitch-RecoilProbe.Before.Pitch,DY=FRotator::NormalizeAxis(Now.Yaw-RecoilProbe.Before.Yaw);
 RecoilSummary=FString::Printf(TEXT("%s kick (%.6f, %.6f) deg; settled turn (%.6f, %.6f) deg against residual x kick (%.6f, %.6f); peak pitch %.6f deg"),Recoil.Profile->Id,RecoilProbe.Kick.X,RecoilProbe.Kick.Y,DP,DY,Keep*RecoilProbe.Kick.X,Keep*RecoilProbe.Kick.Y,RecoilProbe.Peak);
 UE_LOG(LogTemp,Display,TEXT("RECOIL_PROBE %s"),*RecoilSummary);
 return RecoilProbe.Kick.X>0&&FMath::Abs(DP-Keep*RecoilProbe.Kick.X)<1e-3&&FMath::Abs(DY-Keep*RecoilProbe.Kick.Y)<1e-3&&RecoilProbe.Peak>.5*RecoilProbe.Kick.X;
}
